formula:
lo:=LLV(LOW,9); hi:=HHV(HIGH,9);
raw:=IF(hi=lo,DRAWNULL,(CLOSE-lo)/(hi-lo)*100);
rsv:=EMA(raw,3); k:EMA(rsv,3),COLORYELLOW;
d:MA(k,3),COLORWHITE,LIGHTCOLOR2563EB;
goldenCross:=CROSS(k,d); deadCross:=CROSS(d,k);
lowCross:=goldenCross AND k<=50; highCross:=deadCross AND k>=80;
buy:=goldenCross AND d<8; sell:=deadCross AND d>85;
ga:=BARSLAST(REF(goldenCross,1))+1; da:=BARSLAST(REF(deadCross,1))+1;
bottomDivergence:goldenCross AND ga<BARSCOUNT(raw) AND REF(CLOSE,ga)>CLOSE AND k>REF(k,ga),COLORRED;
topDivergence:deadCross AND da<BARSCOUNT(raw) AND REF(CLOSE,da)<CLOSE AND REF(d,da)>d,COLORGREEN;
bottomLineStart:=IF(bottomDivergence,BARSCOUNT(CLOSE)-1-ga+1,DRAWNULL);
topLineStart:=IF(topDivergence,BARSCOUNT(CLOSE)-1-da+1,DRAWNULL);
STICKLINE(k>d,k,d,2.5,0),COLORRED;
STICKLINE(k<=d,k,d,2.5,0),COLORGREEN;
HLINE(90,'逃顶线 90'),COLORGREEN;
HLINE(50,'中轴线 50'),COLORRED;
HLINE(10,'抄底线 10'),COLORYELLOW;
DRAWICON(lowCross,12,1),COLORRED; DRAWICON(highCross,88,2),COLORGREEN;
DRAWTEXT(bottomDivergence,d-5,'加仓'),COLORRED;
DRAWTEXT(topDivergence,d-5,'减仓'),COLORGREEN;
DRAWTEXT(buy,30,'买'),COLORRED; DRAWTEXT(sell,70,'卖'),COLORGREEN;
STICKLINE(buy,3,20,8,0),COLORRED; STICKLINE(sell,85,70,8,0),COLORGREEN; DRAWSEGMENT(bottomDivergence,bottomLineStart,d),COLORRED; DRAWSEGMENT(topDivergence,topLineStart,d),COLORGREEN;
TOOLTIP(k,'K'),COLORYELLOW; TOOLTIP(d,'D'),COLORWHITE; TOOLTIP(bottomDivergence,'底背离',0),COLORRED; TOOLTIP(topDivergence,'顶背离',0),COLORGREEN;
